import { lazy, Suspense, useCallback, useState, useEffect, useRef, type ReactNode } from 'react';
import type { UserProfile } from '../types';
import BackChevron from '../components/BackChevron';
import ParentChildPicker from '../components/ParentChildPicker';
import ParentFeedbackButton from '../components/ParentFeedbackButton';
import ParentHelpPage from '../components/ParentHelpPage';
import ParentOverview from '../components/ParentOverview';
import ParentProfilesPage from '../components/ParentProfilesPage';
import { RefreshIcon } from '../components/ParentSettingIcons';
import ParentSettingsList from '../components/ParentSettingsList';
import ParentSubjectDetail from '../components/ParentSubjectDetail';
import ParentWatchPage from '../components/ParentWatchPage';
import { useParentDashboardStrings } from '../i18n/parent';
import type { Subject } from '../lib/hardestFacts';
import { APP_VERSION } from '../lib/version';
import { isVoiceDebugOn, setVoiceDebug } from '../lib/voiceDebug';
import { setPushPref } from '../lib/push';
import { getActiveProfileId, listProfiles, loadProfileById } from '../lib/storage';
import { daysBetween } from '../lib/utils';
import { fetchWatched, type WatchFetchResult, type WatchPairing, type WatchSnapshot } from '../lib/watch';
import { hasRemoteLinks, listWatched, removeWatched, watchConfigured, type WatchedProfile } from '../lib/watchStore';

// Pages d'information d'« Aide et infos », rarement ouvertes : chargées à la
// demande, comme l'espace parent lui-même.
const PrivacyScreen = lazy(() => import('./PrivacyScreen'));
const ChangelogScreen = lazy(() => import('./ChangelogScreen'));

/** Réglage qui a sa propre page, ouverte depuis la liste de l'accueil. */
type SettingsPage = 'watch' | 'profiles' | 'help';

/** Page ouverte dans l'espace parent, par-dessus son accueil : celle d'une
 *  matière, d'un réglage, ou une page d'information de l'aide. La navigation
 *  (retour, geste système) vit dans App. */
export type ParentPage = Subject | SettingsPage | 'privacy' | 'changelog';

interface ParentDashboardProps {
  // Profil local actif. NULL sur un appareil qui ne fait que suivre un enfant à
  // distance : un parent peut découvrir Tablito en scannant le QR de l'appareil
  // de son enfant, sans jamais créer de profil ici.
  profile: UserProfile | null;
  // Retour de l'écran affiché : de l'accueil vers celui de l'enfant, d'une page
  // vers l'accueil de l'espace parent (cf. backTarget dans App). Absent sur
  // l'accueil quand il n'y a pas de profil local : il n'y a alors nulle part où
  // revenir, l'espace parent EST l'app.
  onBack?: () => void;
  onExport: () => void;
  // Remplace la progression du profil actif par une sauvegarde déjà lue.
  onRestore: (backup: UserProfile) => void;
  // Multi-profils : lance l'onboarding Welcome pour un nouvel enfant.
  onAddProfile: () => void;
  // Supprime le profil actif (avec confirmation côté App).
  onDeleteProfile: () => void;
  // Suivi appairé au boot depuis un `#watch=` : déjà déchiffré par main.tsx, on
  // l'affiche sans second aller-retour réseau.
  initialWatch?: WatchPairing | null;
  // Vrai quand l'espace parent est ouvert par la notification de recap
  // hebdomadaire : change la source affichée par défaut.
  openOnWatched?: boolean;
  // Page ouverte (null = accueil de l'espace parent). L'état vit dans App, avec
  // l'écran : c'est sa table de retour qui ramène d'une page à l'accueil, pour
  // le bouton comme pour le geste système. L'écran reste le même pour App, donc
  // ce composant — et ce qu'il tient (source affichée, instantané distant déjà
  // relu) — reste monté.
  page: ParentPage | null;
  onOpenPage: (page: ParentPage | null) => void;
  // Réglage du profil actif depuis une page de matière (« vus en classe »).
  onUpdateProfile: (update: (profile: UserProfile) => UserProfile) => void;
  // Une progression vient d'être installée, et rendue active, sur cet appareil.
  onProfileInstalled: (profile: UserProfile) => void;
}

// Le suivi sélectionné, tel que relu. `snapshot` est le dernier instantané
// lu : il reste à l'écran pendant une actualisation (`refreshing`) et après une
// relecture ratée (`error`) — sa date dit son âge. Un partage révoqué l'efface,
// c'est définitif. Pas d'état « chargement » : l'absence de vue pour la source
// affichée EST le chargement.
type RemoteView = {
  code: string;
  snapshot: WatchSnapshot | null;
  status: 'ok' | 'refreshing' | 'error' | 'revoked';
};

function viewOf(code: string, result: WatchFetchResult, kept: WatchSnapshot | null): RemoteView {
  if (result === 'revoked') return { code, snapshot: null, status: 'revoked' };
  if (result === 'error') return { code, snapshot: kept, status: 'error' };
  return { code, snapshot: result, status: 'ok' };
}

// Au-delà, la ligne de fraîcheur passe en alerte : l'appareil de l'enfant n'a
// rien déposé depuis (pas joué, ou pas en ligne), et les chiffres ont cet âge.
const STALE_DAYS = 3;

// Ce que dit la ligne de fraîcheur du suivi. Rien pendant le premier
// chargement : le corps de la page dit déjà « Récupération… ».
function freshnessOf(
  view: RemoteView | null,
  name: string,
  t: ReturnType<typeof useParentDashboardStrings>,
): { text: string; alert: boolean } | null {
  if (!view) return null;
  if (view.status === 'revoked') return { text: t.remoteRevoked(name), alert: true };
  if (view.status === 'error' || !view.snapshot) return { text: t.remoteError, alert: true };
  const { updatedAt } = view.snapshot;
  const days = daysBetween(updatedAt, new Date().toISOString());
  if (days >= STALE_DAYS) return { text: t.remoteStale(name, days), alert: true };
  return { text: t.remoteUpdatedAgo(updatedAt), alert: false };
}

// Un enfant que l'espace parent peut afficher : un profil de cet appareil, ou
// un enfant suivi à distance. La clé est son identité stable dans le
// sélecteur (cf. ParentChildPicker).
type ChildEntry =
  | { key: string; name: string; remote: false; id: string }
  | { key: string; name: string; remote: true; entry: WatchedProfile };

const LOCAL = 'local:';
const WATCH = 'watch:';

export default function ParentDashboard({
  profile,
  onBack,
  onExport,
  onRestore,
  onAddProfile,
  onDeleteProfile,
  initialWatch = null,
  openOnWatched = false,
  page,
  onOpenPage,
  onUpdateProfile,
  onProfileInstalled,
}: ParentDashboardProps) {
  const t = useParentDashboardStrings();

  // === Enfants : ceux de cet appareil, et ceux suivis à distance ===
  const [watched, setWatched] = useState<WatchedProfile[]>(listWatched);
  // L'index des profils est relu à chaque rendu (il est minuscule) : une
  // suppression de profil laisse l'espace parent monté, sa liste doit suivre.
  const activeId = getActiveProfileId();
  const children: ChildEntry[] = [
    ...listProfiles().map((p) => ({ key: LOCAL + p.id, name: p.name, remote: false as const, id: p.id })),
    ...watched.map((w) => ({ key: WATCH + w.code, name: w.name, remote: true as const, entry: w })),
  ];
  // Enfant choisi (sa clé) ; null = celui par défaut. Une chaîne et non un
  // objet, parce que c'est l'identité stable dont dépend la relecture :
  // re-choisir l'enfant courant repose la même valeur, React court-circuite le
  // render, et aucune relecture n'est relancée.
  const [chosen, setChosen] = useState<string | null>(() => {
    // Appairage au boot : on ouvre directement sur l'enfant qu'on vient de
    // scanner, c'est la raison même de l'ouverture de l'app.
    if (initialWatch) return WATCH + initialWatch.entry.code;
    // Arrivée par la notification de recap : c'est la progression SUIVIE que le
    // parent vient consulter, pas celle de l'appareil — sans quoi il faudrait
    // encore choisir l'enfant.
    return openOnWatched && watched[0] ? WATCH + watched[0].code : null;
  });
  // Enfant affiché : le choix, tant qu'il existe encore — sinon (suivi arrêté,
  // profil supprimé) le profil actif de l'appareil, ou à défaut le premier
  // enfant suivi.
  const selected =
    children.find((c) => c.key === chosen) ??
    (profile ? children.find((c) => !c.remote && c.id === activeId) : undefined) ??
    children.find((c) => c.remote) ??
    null;
  const watchedEntry = selected?.remote ? selected.entry : null;
  const selectedCode = watchedEntry?.code ?? null;
  const selectedLocalId = selected && !selected.remote ? selected.id : null;
  // Un autre enfant de l'appareil que le profil actif : lu depuis le stockage
  // au moment où le parent le choisit (il ne pratique pas pendant qu'on le
  // regarde). Le profil actif, lui, vient de la prop, à jour après une
  // restauration.
  const [otherLocal, setOtherLocal] = useState<UserProfile | null>(null);
  const selectChild = (key: string) => {
    if (key === selected?.key) return;
    const child = children.find((c) => c.key === key);
    setOtherLocal(child && !child.remote && child.id !== activeId ? loadProfileById(child.id) : null);
    setChosen(key);
  };

  // L'instantané distant, ÉTIQUETÉ du code auquel il appartient : c'est ce qui
  // répond à « ai-je déjà les données de la source affichée ? » sans état de
  // coordination supplémentaire (ni drapeau « saute le premier fetch », ni
  // compteur de rafraîchissement, ni dépendance d'effet à museler).
  const [remote, setRemote] = useState<RemoteView | null>(() =>
    initialWatch ? viewOf(initialWatch.entry.code, initialWatch.snapshot, null) : null,
  );

  // Code de la relecture la plus récemment lancée. Écrit hors render (dans
  // l'effet et dans le handler d'actualisation, cf. react-hooks/refs) : sert à
  // ignorer un résultat qui arrive après une bascule d'onglet, et à ne pas
  // relancer une relecture déjà en vol.
  const inFlightRef = useRef<string | null>(initialWatch?.entry.code ?? null);

  // Relecture au changement de source. La promesse est chaînée INLINE et non
  // déportée dans un useCallback : c'est la forme que la règle
  // react-hooks/set-state-in-effect accepte, et celle déjà employée par
  // usePushPref. Aucun état « chargement » n'est posé ici — l'absence
  // vue pour la source affichée EST le chargement (cf. RemoteView).
  useEffect(() => {
    if (!selectedCode || inFlightRef.current === selectedCode) return;
    const entry = listWatched().find((w) => w.code === selectedCode);
    if (!entry) return;
    inFlightRef.current = selectedCode;
    let cancelled = false;
    void fetchWatched(entry).then((result) => {
      if (!cancelled) setRemote(viewOf(selectedCode, result, null));
    });
    return () => {
      cancelled = true;
    };
  }, [selectedCode]);

  // « Actualiser », et le retour de l'appli au premier plan : même relecture,
  // sans effacer l'instantané affiché (l'icône tourne). `known` est cet
  // instantané : inchangé sur le serveur, il n'est ni retéléchargé ni
  // redéchiffré. Dans un handler d'événement, poser l'état est légitime (à
  // l'inverse de l'effet).
  const refreshRemote = useCallback(async (entry: WatchedProfile, known: WatchSnapshot | null) => {
    inFlightRef.current = entry.code;
    setRemote((prev) => (prev?.code === entry.code && prev.snapshot ? { ...prev, status: 'refreshing' } : null));
    const result = await fetchWatched(entry, known);
    if (inFlightRef.current !== entry.code) return;
    setRemote((prev) => viewOf(entry.code, result, prev?.code === entry.code ? prev.snapshot : null));
  }, []);

  // N'est vrai que si l'état chargé correspond bien à la source affichée.
  const remoteView = watchedEntry && remote?.code === watchedEntry.code ? remote : null;
  const remoteSnapshot = remoteView?.snapshot ?? null;

  // Un parent qui laisse l'espace parent ouvert et y revient le lendemain doit
  // voir la progression du jour, pas celle de la veille.
  useEffect(() => {
    if (!watchedEntry) return;
    const onVisible = () => {
      if (document.visibilityState === 'visible') void refreshRemote(watchedEntry, remoteSnapshot);
    };
    document.addEventListener('visibilitychange', onVisible);
    return () => document.removeEventListener('visibilitychange', onVisible);
  }, [watchedEntry, remoteSnapshot, refreshRemote]);
  // Profil réellement rendu : un enfant de l'appareil, ou l'instantané de
  // l'enfant suivi.
  const shown = watchedEntry
    ? remoteSnapshot?.profile ?? null
    : selectedLocalId === activeId
      ? profile
      : otherLocal;
  // Seul le profil actif se modifie d'ici : ni un autre enfant de l'appareil,
  // ni un enfant suivi (ses réglages se font sur son propre appareil).
  const editable = shown === profile;
  const shownName = shown?.name ?? watchedEntry?.name ?? '';
  const freshness = freshnessOf(remoteView, shownName, t);
  // « Envoyer un avis » : sur l'accueil et sur la page d'une matière, là où
  // un parent repère un souci. L'avis joint le profil affiché.
  const feedbackButton = (
    <ParentFeedbackButton
      profile={shown}
      source={watchedEntry ? { kind: 'watched', fetchedAt: remoteSnapshot?.updatedAt } : { kind: 'local' }}
    />
  );

  // Suivi qu'on vient d'appairer (au démarrage ou par le scanner) : l'appareil
  // demande ce qu'il doit faire de l'enfant, le suivre ou le faire jouer ici
  // aussi. Un seul QR côté enfant, et c'est l'appareil qui scanne qui choisit
  // (specs §14.4).
  const [justPaired, setJustPaired] = useState<string | null>(initialWatch?.entry.code ?? null);

  // Appairage réussi depuis la page du suivi à distance (cf. ParentWatchPairing).
  const handlePaired = (paired: WatchPairing) => {
    setJustPaired(paired.entry.code);
    setWatched(listWatched());
    // L'instantané est déjà déchiffré : on l'étiquette, et marquer le code comme
    // servi évite que l'effet relance une relecture inutile juste après.
    inFlightRef.current = paired.entry.code;
    setRemote(viewOf(paired.entry.code, paired.snapshot, null));
    setChosen(WATCH + paired.entry.code);
    // Retour à l'accueil, sur l'enfant qu'on vient d'appairer : c'est lui qu'on
    // voulait voir.
    onOpenPage(null);
  };

  const handleStopWatching = (code: string) => {
    const list = removeWatched(code);
    setWatched(list);
    // Plus aucun enfant suivi ni partagé : le recap hebdomadaire n'a plus rien
    // à annoncer, et sa ligne disparaît avec la liste — le laisser actif condamnerait le
    // parent à une notification hebdomadaire qu'il ne pourrait plus éteindre
    // depuis l'app.
    if (!hasRemoteLinks()) void setPushPref('weekly', false);
  };

  // L'enfant suivi joue aussi sur cet appareil : l'instantané affiché est le
  // profil complet, installé ici comme profil synchronisé avec son autre
  // appareil (cf. lib/sync). C'est aussi le chemin d'un changement de
  // téléphone : on retire ensuite l'enfant de l'ancien. Le choix fait juste
  // après l'appairage vaut confirmation ; le bouton permanent en demande une.
  const playHere = async (entry: WatchedProfile, snapshot: UserProfile, confirm: boolean) => {
    if (confirm && !window.confirm(t.playHereConfirm(snapshot.name))) return;
    const { joinAsPlayer } = await import('../lib/sync');
    const installed = joinAsPlayer(entry, snapshot);
    setWatched(listWatched());
    onProfileInstalled(installed);
  };

  // Page d'une matière, sur le profil affiché. Une page ne s'ouvre que depuis
  // une carte de l'accueil, qui n'existe qu'avec un profil affiché ; la clé
  // repart de zéro (niveau actif, bascules) si la source changeait dessous.
  if ((page === 'math' || page === 'conj' || page === 'irr') && shown) {
    return (
      <div className="parent-dashboard parent-dashboard--subject">
        <Header
          onBack={onBack}
          backLabel={t.backToOverview}
          eyebrow={shownName}
          title={{ math: t.math, conj: t.conjugations, irr: t.irregularVerbs }[page]}
        >
          {feedbackButton}
        </Header>
        <ParentSubjectDetail
          key={selected?.key ?? 'none'}
          profile={shown}
          subject={page}
          onUpdateProfile={editable ? onUpdateProfile : undefined}
        />
      </div>
    );
  }

  // Pages d'information, plein écran avec leur propre en-tête. Toujours un
  // retour (vers « Aide et infos ») : cf. backTarget dans App. Leur frontière
  // de chargement est ici et non celle d'App : sous Preact, un chargement
  // suspendu recrée tout ce que sa frontière enveloppe, et l'espace parent y
  // perdrait sa source affichée.
  if ((page === 'privacy' || page === 'changelog') && onBack) {
    return (
      <Suspense fallback={null}>
        {page === 'privacy' ? <PrivacyScreen onBack={onBack} /> : <ChangelogScreen onBack={onBack} />}
      </Suspense>
    );
  }

  // Page d'un réglage. Ce qu'elles règlent tient à l'APPAREIL (ses profils, ses
  // partages, ses suivis), pas au profil affiché.
  if (page === 'watch' || page === 'help' || (page === 'profiles' && profile)) {
    const title: Record<SettingsPage, string> = {
      watch: t.watchTitle,
      profiles: t.profilesTitle,
      help: t.helpTitle,
    };
    return (
      <div className="parent-dashboard parent-dashboard--settings">
        <Header onBack={onBack} backLabel={t.backToOverview} eyebrow={t.settingsEyebrow} title={title[page]} />
        {page === 'watch' && (
          <ParentWatchPage
            watched={watched}
            onPaired={handlePaired}
            onStopWatching={handleStopWatching}
            onProfileInstalled={onProfileInstalled}
          />
        )}
        {page === 'profiles' && profile && (
          <ParentProfilesPage
            profile={profile}
            onAddProfile={onAddProfile}
            onDeleteProfile={onDeleteProfile}
            onExport={onExport}
            onRestore={onRestore}
          />
        )}
        {page === 'help' && (
          <ParentHelpPage
            onShowChangelog={() => onOpenPage('changelog')}
            onShowPrivacy={() => onOpenPage('privacy')}
          />
        )}
      </div>
    );
  }

  return (
    <div className="parent-dashboard">
      <Header onBack={onBack} backLabel={t.back} eyebrow={t.parentArea} title={shownName}>
        {feedbackButton}
      </Header>

      {/* Un seul sélecteur pour tous les enfants, ceux de l'appareil comme
          ceux suivis à distance — seulement s'il y a vraiment un choix. */}
      {children.length > 1 && (
        <ParentChildPicker items={children} selected={selected?.key ?? null} onSelect={selectChild} />
      )}

      {/* Fraîcheur du suivi : sans elle, un appareil enfant éteint depuis une
          semaine afficherait des stats périmées sans le dire. Une ligne de
          légende, pas une carte : elle ne prend de couleur que lorsqu'elle porte
          une alerte. Une section pour les marges, sous l'en-tête comme sous le
          sélecteur. */}
      {watchedEntry && freshness && (
        <div className="parent-section parent-remote-line">
          <p
            className={`parent-section-subtitle parent-remote-status${freshness.alert ? ' parent-remote-status--alert' : ''}`}
          >
            {freshness.text}
          </p>
          {remoteView?.status !== 'revoked' && (
            <button
              className={`parent-remote-refresh${remoteView?.status === 'refreshing' ? ' is-spinning' : ''}`}
              onClick={() => void refreshRemote(watchedEntry, remoteSnapshot)}
              disabled={remoteView?.status === 'refreshing'}
              aria-label={t.remoteRefresh}
              title={t.remoteRefresh}
            >
              <RefreshIcon />
            </button>
          )}
        </div>
      )}

      {watchedEntry && remoteSnapshot && justPaired === watchedEntry.code && (
        <div className="parent-section">
          <div className="parent-card parent-empty">
            <p className="parent-empty-text">{t.pairChoice(shownName)}</p>
            <button
              className="parent-action-btn"
              onClick={() => void playHere(watchedEntry, remoteSnapshot.profile, false)}
            >
              {t.playHere(shownName)}
            </button>
            <button className="parent-action-btn" onClick={() => setJustPaired(null)}>
              {t.followOnly}
            </button>
            <p className="parent-section-subtitle">{t.pairChoiceHint}</p>
          </div>
        </div>
      )}

      {shown ? (
        <ParentOverview profile={shown} onOpenSubject={onOpenPage} editable={editable} />
      ) : watchedEntry ? (
        <div className="parent-section">
          <p className="parent-section-subtitle">
            {remoteView ? t.remoteNoData : t.remoteLoading}
          </p>
        </div>
      ) : (
        // Ni profil ici ni enfant suivi (un QR périmé scanné sans Tablito) :
        // rien à montrer, et le chemin pour suivre un enfant en tête.
        <div className="parent-section">
          <div className="parent-card parent-empty">
            <p className="parent-empty-text">{t.emptyProgress}</p>
            {watchConfigured() && (
              <button className="parent-action-btn" onClick={() => onOpenPage('watch')}>
                {t.watchFollow}
              </button>
            )}
          </div>
        </div>
      )}

      {/* Au-delà : ce qu'on règle, par opposition à ce qu'on consulte. */}
      <div className="parent-section parent-settings-start">
        <h2 className="parent-overline">{t.settings}</h2>
        <ParentSettingsList hasLocalProfile={profile !== null} watched={watched} onOpenPage={onOpenPage} />
      </div>

      {/* L'enfant suivi pratique aussi ici : le faire jouer sur cet appareil.
          Puis, sur un appareil qui ne fait que suivre, la porte vers un profil
          local, à la place de la ligne « Profils et sauvegarde ». */}
      {watchedEntry && remoteSnapshot && justPaired !== watchedEntry.code && (
        <div className="parent-section">
          <p className="parent-section-subtitle">{t.playHereHint(shownName)}</p>
          <div className="parent-actions">
            <button
              className="parent-action-btn"
              onClick={() => void playHere(watchedEntry, remoteSnapshot.profile, true)}
            >
              {t.playHere(shownName)}
            </button>
          </div>
        </div>
      )}
      {!profile && (
        <div className="parent-section">
          <div className="parent-actions">
            <button className="parent-action-btn" onClick={onAddProfile}>
              {t.createLocalProfile}
            </button>
          </div>
          <p className="parent-section-subtitle parent-note">{t.profilesSubtitleWatcher}</p>
        </div>
      )}

      <VersionLine t={t} />
    </div>
  );
}

const VERSION_TAPS = 7;
const VERSION_TAP_GAP_MS = 1000;

/**
 * Le numéro de version, et l'easter egg du journal vocal : comme les options
 * pour les développeurs d'Android, 7 touches rapprochées affichent son bandeau,
 * 7 autres le masquent (le bandeau a aussi son bouton « Désactiver »). Le
 * journal, lui, se tient toujours (lib/voiceDebug).
 */
function VersionLine({ t }: { t: ReturnType<typeof useParentDashboardStrings> }) {
  const taps = useRef({ count: 0, last: 0 });
  // L'état choisi au dernier geste, null avant le premier.
  const [toggled, setToggled] = useState<boolean | null>(null);
  const tap = () => {
    const now = Date.now();
    const tapped = taps.current;
    tapped.count = now - tapped.last > VERSION_TAP_GAP_MS ? 1 : tapped.count + 1;
    tapped.last = now;
    if (tapped.count < VERSION_TAPS) return;
    tapped.count = 0;
    const on = !isVoiceDebugOn();
    setVoiceDebug(on);
    setToggled(on);
  };
  return (
    <>
      <button type="button" className="parent-version" aria-label={t.appVersionLabel} onClick={tap}>
        v{APP_VERSION}
      </button>
      {toggled !== null && (
        <p className="parent-version-notice" role="status">
          {toggled ? t.voiceDebugOn : t.voiceDebugOff}
        </p>
      )}
    </>
  );
}

interface HeaderProps {
  onBack?: () => void;
  backLabel: string;
  eyebrow: string;
  title: string;
  /** Action à droite du titre (« Envoyer un avis »). */
  children?: ReactNode;
}

// En-tête commun à l'accueil de l'espace parent et à ses pages.
function Header({ onBack, backLabel, eyebrow, title, children }: HeaderProps) {
  return (
    <div className="parent-header">
      {onBack && (
        <button className="parent-back-btn" onClick={onBack} aria-label={backLabel}>
          <BackChevron />
        </button>
      )}
      <div className="parent-header-titles">
        <div className="parent-eyebrow">{eyebrow}</div>
        <div className="parent-title">{title}</div>
      </div>
      {children}
    </div>
  );
}
